head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods27000";
scwin.mainIndex = "";
scwin.chkboxAllChk = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — contnId, index

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_pageCount", fn: function(){ return ((dma_page.get("pageCount") ?? (() => { throw new Error("unresolved:" + "page.pageCount"); })())!==0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_39", entity: "dlt_bzIdList", countIds: [], cells: [{ childId: "ipt_sprtRoomGrpIdArr", fn: function (v, i) { return String(v("sprtBzDtlId")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return " onclick=\"chkboxAllChk()\">" + String(dlt_bzIdList.getCellData(0, "sprtBzDtlNm")); } },
        { childId: "__rb1", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [0" + String(dma_sprtroomForm.get("pageIndex")) + "/" + String(dma_page.get("pageCount")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const contnId = (String(((dma_pageContext.get("contnId") ?? "")) === null ? '' : ((dma_pageContext.get("contnId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("contnId") ?? "")) === null ? '' : ((dma_pageContext.get("contnId") ?? ""))));
        const index = (String(((dma_pageContext.get("index") ?? "")) === null ? '' : ((dma_pageContext.get("index") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("index") ?? "")) === null ? '' : ((dma_pageContext.get("index") ?? ""))));
        if (contnId.length > 0) {
            await scwin.detail(contnId, index, 'init');
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods27000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.chkboxAllChk = chkboxAllChk;
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods27000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_44_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_44_onclick = async function(e){
    try {
        await scwin.search(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods27000.input_44_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.search(1);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods27000.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name resourceTable_oncellclick
 * @description resourceTable 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.resourceTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resourceRoomList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resourceRoomList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { scwin.fileDownload(r["sprtRoomNo"], r["attachSeq"], r["attachFileNm"]); return; } await scwin.detail(r["sprtRoomNo"], r["index"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'resourceTable.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_detail
 * @description detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_detail = async function () {
    const sbmOptions = {
        id: "tx_fn_detail",
        method: "post",
        action: "/sprtroom/resourceRoom.do",
        ref: "dma_detailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/sprtroom/resourceRoom.do?method=readResourceRoomDetail&sprtRoomNo=",
        ref: "dma_loadListReq",
        target: "dlt_bzIdList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods27000.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_102").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_1_ipt_keyword
 * @description on enter 1 ipt keyword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_keyword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods27000.__on_enter_1_ipt_keyword' }); }
};

/**
 * @method
 * @name __on_enter_2_ipt_chrginstid
 * @description on enter 2 ipt chrginstid 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_chrginstid = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods27000.__on_enter_2_ipt_chrgInstId' }); }
};

/**
 * @method
 * @name resourceTable_fillAct
 * @description resource Table fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.resourceTable_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_resourceRoomList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'resourceTable.fillAct' });
    }
};

/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {*} ipt_sprtRoomNo ipt_sprtRoomNo
 * @param {Number} index index
 * @param {*} init init
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.detail = async function (ipt_sprtRoomNo, index, init) {
    $('#ipt_sprtRoomNo', $('#searchForm')).val(ipt_sprtRoomNo);
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods27010/jldods27010.xml");
    $('#ipt_method', $('#searchForm')).val("readResourceRoomDetail");
    await scwin.tx_fn_detail();
};

/**
 * @method
 * @name setInqCnt
 * @description set Inq Cnt 처리
 * @param {*} inqCnt inqCnt
 * @returns {void}
 * @hidden N
 */
scwin.setInqCnt = function (inqCnt) {
    $('#inqCnt' + scwin.mainIndex).html(inqCnt);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} ipt_pageIndex ipt_pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (ipt_pageIndex) {
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await alertE("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await alertE("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await alertE("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods27000/jldods27000.xml");
    $('#ipt_method', $('#searchForm')).val("readResourceRoomList");
    $('#searchForm').submit();
};

/**
 * @method
 * @name fileDownload
 * @description file Download 처리
 * @param {*} sprt_room_no sprt_room_no
 * @param {*} attach_seq attach_seq
 * @param {*} attach_file_nm attach_file_nm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods25000/jldods25000.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
};

/**
 * @method
 * @name chkboxAll
 * @description chkbox All 처리
 * @param {*} allChecked allChecked
 * @returns {void}
 * @hidden N
 */
scwin.chkboxAll = function (allChecked) {
    if (allChecked) {
        $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).prop("checked", false);
    }
};

function chkboxAllChk() {
    let cnt = 0;
    const totCnt = $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).length - 1;
    $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).each(function() {
            if (this.value !== "ALL" && this.checked) {
                cnt++;
            }
    });
    if (cnt === totCnt) {
        $("input[id=ipt_sprtRoomGrpIdAll]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[id=ipt_sprtRoomGrpIdAll]", $('#searchForm')).prop("checked", false);
    }
}

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name krxpage_pagenavigator_102_onclick
 * @description krxpage_pagenavigator_102 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_102_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_102.page' }); } await scwin.tx_load_list(); };
